        for (int j = 0; j <= i; j++) {
            firstHalfTotal += nums[j];
        }
        double firstHalfAverage = firstHalfTotal / (i + 1);
        double secondHalfTotal = 0;
        for (int j = nums.length - 1; j >= nums.length / 2; j--) {
