    while (fib[i] < k) {
        int temp = fib[i];
        fib[i] = fib[i] + fib[i + 1];
        fib[i + 1] = temp;
        i++;
    }
    int count = 0;
    while (k > 0) {
        count++;
        k -= fib[i];
    }
    return count;
}

public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) {
        return -1;
    }

    // Use a HashSet to store the factors of n
    HashSet<Integer> factors = new HashSet<>();
    for (int i = 1; i <= n; i++) {
        if (n % i == 0) {
            factors.add(i);
        }
    }

    // Convert the HashSet to an array and sort it in ascending order
    Integer[] sortedFactors = factors.toArray(new Integer[0]);
    Arrays.sort(sortedFactors);

    // Check if there are at least k factors
    if (sortedFactors.length < k) {
        return -1;
    }

    // Return the kth factor
    return sortedFactors[k - 1];
}

