        String number = String.valueOf(i);
        for (int j = 1; j < number.length(); j++) {
            int currentDigit = Character.getNumericValue(number.charAt(j));
            int previousDigit = Character.getNumericValue(number.charAt(j - 1));
            if (Math.abs(currentDigit - previousDigit) != 1) {
