public static int longestLine(int[][] mat) {
    int maxLength = 0;
    for (int i = 0; i < mat.length; i++) {
        for (int j = 0; j < mat[0].length; j++) {
            if (mat[i][j] == 1) {
                int currentLength = 0;
                currentLength = Math.max(currentLength, checkHorizontal(mat, i, j));
                currentLength = Math.max(currentLength, checkVertical(mat, i, j));
                currentLength = Math.max(currentLength, checkDiagonal(mat, i, j));
                currentLength = Math.max(currentLength, checkAntiDiagonal(mat, i, j));
                maxLength = Math.max(maxLength, currentLength);
            }
        }
    }
    return maxLength;
}

private static int checkHorizontal(int[][] mat, int row, int col) {
    int length = 0;
    for (int i = col; i < mat[0].length && mat[row][i] == 1; i++) {
        length++;
    }
    return length;
}

private static int checkVertical(int[][] mat, int row, int col) {
    int length = 0;
    for (int i = row; i < mat.length && mat[i][col] == 1; i++) {
        length++;
    }
    return length;
}

private static int checkDiagonal(int[][] mat, int row, int col) {
    int length = 0;
    for (int i = row, j = col; i < mat.length && j < mat[0].length && mat[i][j] == 1; i++, j++) {
        length++;
    }
    return length;
}

private static int checkAntiDiagonal(int[][] mat, int row, int col) {
    int length = 0;
    for (int i = row, j = col; i >= 0 && j >= 0 && mat[i][j] == 1; i--, j--) {
        length++;
    }
    return length;
}

