public static int squarePermutations(int[] A) {
    int n = A.length;
    int count = 0;
    Map<Integer, Integer> map = new HashMap<>();

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i != j && A[i] + A[j] <= A[i] * A[j]) {
                int key = (A[i] * A[j] - A[i - 1] - A[j - 1]) / 2;
                map.put(key, map.getOrDefault(key, 0) + 1);
            }
        }
    }

    for (int key : map.keySet()) {
        int value = map.get(key);
        count += value * (value - 1) / 2;
    }

    return count;
}

public static int largestRectangleArea(int[] heights) {
    int maxArea = 0;
    Stack<Integer> stack = new Stack<>();
    stack.push(-1);
    for (int i = 0; i < heights.length; i++) {
        while (stack.peek() != -1 && heights[i] < heights[stack.peek()]) {
            int top = stack.pop();
            int width = i - stack.peek() - 1;
            maxArea = Math.max(maxArea, heights[top] * width);
        }
        stack.push(i);
    }
    while (stack.peek() != -1) {
        int top = stack.pop();
        int width = heights.length - stack.peek() - 1;
        maxArea = Math.max(maxArea, heights[top] * width);
    }
    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    int[] output = new int[mat.length * mat[0].length];
    int row = 0, col = 0, index = 0;

    while (row < mat.length && col < mat[0].length) {
        // Traverse the top-left to bottom-right diagonal
        for (int i = row; i < mat.length && col < mat[0].length; i++, col++) {
            output[index++] = mat[i][col];
        }

        // Traverse the bottom-left to top-right diagonal
        for (int i = row + 1; i < mat.length && col >= 0; i++, col--) {
            output[index++] = mat[i][col];
        }

        row++;
    }

    return output;
}

